def _is_enum_subclass(cls: nodes.ClassDef) -> bool:
    """Return whether cls is a subclass of an Enum."""
    return cls.is_subtype_of("enum.Enum") or cls.is_subtype_of("enum.IntEnum") or cls.is_subtype_of("enum.Flag")

def infer_call_result(
    self,
    caller: SuccessfulInferenceResult | None,
    context: InferenceContext | None = None,
) -> Iterator[InferenceResult]:
    """Infer what the function returns when called."""
    if context is None:
        context = InferenceContext()
    if self.is_generator():
        if isinstance(self, AsyncFunctionDef):
            generator_cls: type[bases.Generator] = bases.AsyncGenerator
        else:
            generator_cls = bases.Generator
        result = generator_cls(self, generator_initial_context=context)
        yield result
        return
    # This is really a gigantic hack to work around metaclass generators
    # that return transient class-generating functions. Pylint's AST structure
    # cannot handle a base class object that is only used for calling __new__,
    # but does not contribute to the inheritance structure itself. We inject
    # a fake class into the hierarchy here for several well-known metaclass
    # generators, and filter it out later.
    if (
        self.name == "with_metaclass"
        and caller is not None
        and self.args.args
        and len(self.args.args) == 1
        and self.args.vararg is not None
    ):
        if isinstance(caller.args, node_classes.Arguments):
            assert caller.args.args is not None
            call_args = caller.args.args
        elif isinstance(caller.args, list):
            call_args = caller.args
        else:
            raise TypeError(  # pragma: no cover
                f"caller.args was neither Arguments nor list; got {type(caller.args)}"
            )
        if not call_args:
            # ``with_metaclass()`` called without a metaclass argument is
            # invalid; there is nothing to infer.
            raise InferenceError(
                "with_metaclass() call has no metaclass argument",
                node=self,
                context=context,
            )
        metaclass = next(call_args[0].infer(context), None)
        if isinstance(metaclass, ClassDef):
            class_bases = [_infer_last(x, context) for x in call_args[1:]]
            new_class = ClassDef(
                name="temporary_class",
                lineno=0,
                col_offset=0,
                end_lineno=0,
                end_col_offset=0,
                parent=SYNTHETIC_ROOT,
            )
            new_class.hide = True
            new_class.postinit(
                bases=[
                    base
                    for base in class_bases
                    if not isinstance(base, util.UninferableBase)
                ],
                body=[],
                decorators=None,
                metaclass=metaclass,
            )
            yield new_class
            return
    returns = self._get_return_nodes_skip_functions()

    first_return = next(returns, None)
    if not first_return:
        if protocols._is_stub_node(self) and self._is_stub_placeholder_body(
            self.body
        ):
            if self.returns is not None:
                yield from protocols.infer_instance_from_annotation(
                    self.returns, ctx=context
                )
            else:
                yield util.Uninferable
            return

        if self.body:
            # A body that is only ``...`` is a placeholder, like ``pass``:
            # it does not mean the function returns ``None``.
            if self._is_stub_placeholder_body(self.body) or self.is_abstract(
                pass_is_abstract=True, any_raise_is_abstract=True
            ):
                yield util.Uninferable
            else:
                yield node_classes.Const(None)
            return

        # Builtin dunder methods have empty bodies, return Uninferable.
        if (
            len(self.body) == 0
            and self.name.startswith("__")
            and self.name.endswith("__")
            and self.root().qname() == "builtins"
        ):
            yield util.Uninferable
            return

        raise InferenceError("The function does not have any return statements")

    for returnnode in itertools.chain((first_return,), returns):
        if returnnode.value is None:
            yield node_classes.Const(None)
        else:
            try:
                yield from returnnode.value.infer(context)
            except InferenceError:
                yield util.Uninferable

def dumps(data: Mapping, sort_keys: bool = False) -> str:
    """
    Dumps a TOMLDocument into a string.
    """
    if not isinstance(data, TOMLDocument) and isinstance(data, Mapping):
        data = item(dict(data), _sort_keys=sort_keys)

    try:
        # data should be a `TOMLDocument` (and therefore implement `as_string`)
        # for all type safe invocations of this function
        return data.as_string()  # type: ignore[attr-defined]
    except AttributeError as ex:
        msg = f"Expecting Mapping or TOMLDocument, {type(data)} given"
        raise TypeError(msg) from ex

def _get_last_index_before_table(self) -> int:
    last_index = -1
    for i, (k, v) in enumerate(self._body):
        if isinstance(v, Null):
            continue  # Null elements are inserted after deletion

        if isinstance(v, Whitespace) and not v.is_fixed():
            continue

        if isinstance(v, (Table, AoT)) and (k is None or not k.is_dotted()):
            break
        last_index = i
    return last_index + 1

def __delitem__(self, key: int | slice) -> None:  # type: ignore[override]
    length = len(self)
    list.__delitem__(self, key)

    if isinstance(key, slice):
        start, stop, step = key.indices(length)
        indices_to_remove = list(range(start, stop, step))
    else:
        indices_to_remove = [length + key if key < 0 else key]
    for i in sorted(indices_to_remove, reverse=True):
        try:
            idx = self._index_map[i]
        except KeyError as e:
            if not isinstance(key, slice):
                raise IndexError("list index out of range") from e
        else:
            group_rm = self._value[idx]
            del self._value[idx]
            if (
                idx == 0
                and len(self._value) > 0
                and (ind := self._value[idx].indent)
                and "\n" not in ind.s
            ):
                # Remove the indentation of the first item if not newline
                self._value[idx].indent = None
            comma_in_indent = (
                group_rm.indent is not None and "," in group_rm.indent.s
            )
            comma_in_comma = group_rm.comma is not None and "," in group_rm.comma.s
            if comma_in_indent and comma_in_comma:
                # Removed group had both commas. Add one to the next group.
                group = self._value[idx] if len(self._value) > idx else None
                if group is not None:
                    if group.indent is None:
                        group.indent = Whitespace(",")
                    elif "," not in group.indent.s:
                        # Insert the comma after the newline
                        try:
                            newline_index = group.indent.s.index("\n")
                            group.indent._s = (
                                group.indent.s[: newline_index + 1]
                                + ","
                                + group.indent.s[newline_index + 1 :]
                            )
                        except ValueError:
                            group.indent._s = "," + group.indent.s
            elif not comma_in_indent and not comma_in_comma:
                # Removed group had no commas. Remove the next comma found.
                for j in range(idx, len(self._value)):
                    group = self._value[j]
                    if group.indent is not None and "," in group.indent.s:
                        group.indent._s = group.indent.s.replace(",", "", 1)
                        break
            if group_rm.indent is not None and "\n" in group_rm.indent.s:
                # Restore the removed group's newline onto the next group
                # if the next group does not have a newline.
                # i.e. the two were on the same line
                group = self._value[idx] if len(self._value) > idx else None
                if group is not None and (
                    group.indent is None or "\n" not in group.indent.s
                ):
                    group.indent = group_rm.indent

    if len(self._value) > 0:
        v = self._value[-1]
        if not v.is_whitespace():
            # remove the comma of the last item
            v.comma = None

    self._reindex()

def get_meta_refresh(
    response: TextResponse,
    ignore_tags: Iterable[str] = ("script", "noscript"),
) -> tuple[None, None] | tuple[float, str]:
    """Parse the http-equiv refresh parameter from the given response"""
    key = (response, ignore_tags)
    if key not in _metaref_cache:
        text = response.text[0:4096]
        _metaref_cache[key] = html.get_meta_refresh(
            text, response.url, response.encoding, ignore_tags=ignore_tags
        )
    return _metaref_cache[key]

@staticmethod
def _get_tag_name(elem: lxml.etree._Element) -> str:
    if not isinstance(elem.tag, str):
        return ""
    _, _, localname = elem.tag.partition("}")
    return localname or elem.tag

@_warn_spider_arg
def process_request(
    self, request: Request, spider: Spider | None = None
) -> Request | Response | None:
    if request.meta.get("dont_cache", False):
        return None

    # Skip uncacheable requests
    if not self.policy.should_cache_request(request):
        request.meta["_dont_cache"] = True  # flag as uncacheable
        return None

    # Look for cached response and check if expired
    cachedresponse: Response | None = self.storage.retrieve_response(
        spider, request
    )
    if cachedresponse is None:
        self.stats.inc_value("httpcache/miss")
        if self.ignore_missing:
            self.stats.inc_value("httpcache/ignore")
            raise IgnoreRequest(f"Ignored request not in cache: {request}")
        return None  # first time request

    # Return cached response only if not expired
    cachedresponse.flags.append("cached")
    if self.policy.is_cached_response_fresh(cachedresponse, request):
        self.stats.inc_value("httpcache/hit")
        return cachedresponse

    # Keep a reference to cached response to avoid a second cache lookup on
    # process_response hook
    request.meta["cached_response"] = cachedresponse

    return None

def add_cookie_header(self, request: Request) -> None:
    wreq = WrappedRequest(request)
    self.policy._now = self.jar._now = int(time.time())  # type: ignore[attr-defined]

    # the cookiejar implementation iterates through all domains
    # instead we restrict to potential matches on the domain
    req_host = urlparse_cached(request).hostname
    if not req_host:
        return

    if not IPV4_RE.search(req_host):
        hosts = potential_domain_matches(req_host)
        if "." not in req_host:
            hosts.append(req_host)
            hosts.append(req_host + ".local")
    else:
        hosts = [req_host]

    cookies = []
    for host in hosts:
        if host in self.jar._cookies:  # type: ignore[attr-defined]
            cookies.extend(self.jar._cookies_for_domain(host, wreq))  # type: ignore[attr-defined]

    attrs = self.jar._cookie_attrs(cookies)  # type: ignore[attr-defined]
    if attrs and not wreq.has_header("Cookie"):
        wreq.add_unredirected_header("Cookie", "; ".join(attrs))

    self.processed += 1
    if self.processed % self.check_expired_frequency == 0:
        # This is still quite inefficient for large number of cookies
        self.jar.clear_expired_cookies()

def __setitem__(self, key: _KT, value: _VT) -> None:
    if self.limit is not None:
        if self.limit == 0:
            return
        if key not in self:
            while len(self) >= self.limit:
                self.popitem(last=False)
    super().__setitem__(key, value)

def datatype_sql(self, expression: exp.DataType) -> str:
    # Check if this is a temporal type that needs precision handling. Fabric limits temporal
    # types to max 6 digits precision. When no precision is specified, we default to 6 digits.
    if expression.is_type(*exp.DataType.TEMPORAL_TYPES) and not expression.is_type(exp.DataType.Type.DATE):
        # Get the current precision (first expression if it exists)
        precision_param = expression.find(exp.DataTypeParam)
        target_precision = 6

        if precision_param and precision_param.this.is_int:
            # Cap precision at 6
            current_precision = precision_param.this.to_py()
            target_precision = min(current_precision, 6)
        else:
            # If precision exists but is not an integer, default to 6
            target_precision = 6

        # Create a new expression with the target precision
        expression = exp.DataType(
            this=expression.this,
            expressions=[exp.DataTypeParam(this=exp.Literal.number(target_precision))],
        )

    return super().datatype_sql(expression)

def _parse_for_in(self) -> exp.ForIn:
    this = self._parse_id_var()
    self._match_text_seq("IN")
    self._parse_range()
    self._match_text_seq("DO")
    return self.expression(exp.ForIn, this=this, expression=self._parse_statement())

def _partially_consume_prefix(self, prefix, column):
    lines = []
    current_line = ""
    current_column = 0
    wait_for_nl = False
    for char in prefix:
        current_line += char
        if wait_for_nl:
            if char == '\n':
                if current_line.strip() and current_column < column:
                    res = ''.join(lines)
                    return res, prefix[len(res):]

                lines.append(current_line)
                current_line = ""
                current_column = 0
                wait_for_nl = False
        elif char == ' ':
            current_column += 1
        elif char == '\t':
            current_column += 4
        elif char == '\n':
            # unexpected empty line
            lines.append(current_line)
            current_line = ""
            current_column = 0
        else:
            # indent is finished
            wait_for_nl = True
    return ''.join(lines), current_line

def get_future_imports(node: Node) -> Set[str]:
    """Return a set of __future__ imports in the file."""
    imports = set()
    for child in node.children:
        if child.type != syms.simple_stmt:
            break
        first_child = child.children[0]
        if isinstance(first_child, Leaf):
            # Continue looking if we see a docstring; otherwise stop.
            if (
                len(child.children) == 2
                and first_child.type == token.STRING
                and child.children[1].type == token.NEWLINE
            ):
                continue
            else:
                break
        elif first_child.type == syms.import_from:
            module_name = first_child.children[1]
            if not isinstance(module_name, Leaf) or module_name.value != "__future__":
                break
            for import_from_child in first_child.children[3:]:
                if isinstance(import_from_child, Leaf):
                    if import_from_child.type == token.NAME:
                        imports.add(import_from_child.value)
                else:
                    assert import_from_child.type == syms.import_as_names
                    for leaf in import_from_child.children:
                        if isinstance(leaf, Node) and leaf.type == syms.import_as_name:
                            imports.add(leaf.children[0].value)
        else:
            break
    return imports

def gen_python_files_in_dir(
    path: Path,
    root: Path,
    include: Pattern[str],
    exclude: Pattern[str],
    report: "Report",
) -> Iterator[Path]:
    """Generate all files under `path` whose paths are not excluded by the
    `exclude` regex, but are included by the `include` regex.

    `report` is where output about exclusions goes.
    """
    assert root.is_absolute(), f"INTERNAL ERROR: `root` must be absolute but is {root}"
    for child in path.iterdir():
        normalized_path = "/" + child.resolve().relative_to(root).as_posix()
        if child.is_dir():
            normalized_path += "/"
        exclude_match = exclude.search(normalized_path)
        if exclude_match and exclude_match.group(0):
            report.path_ignored(child, f"matches the --exclude regular expression")
            continue

        if child.is_dir():
            yield from gen_python_files_in_dir(child, root, include, exclude, report)

        elif child.is_file():
            include_match = include.search(normalized_path)
            if include_match and include_match.group(0):
                yield child

def dump_to_file(*output: str) -> str:
    """Dump `output` to a temporary file. Return path to the file."""
    import tempfile

    with tempfile.NamedTemporaryFile(
        mode="w", prefix="blk_", suffix=".log", delete=False
    ) as f:
        for lines in output:
            f.write(lines)
            if lines and lines[-1] != "\n":
                f.write("\n")
        return f.name

def get_host_regex(self, spider):
    """Override this method to implement a different offsite policy"""
    allowed_domains = getattr(spider, 'allowed_domains', None)
    if not allowed_domains:
        return re.compile('')  # allow all by default
    url_pattern = re.compile("^https?://.*$")
    for domain in allowed_domains:
        if url_pattern.match(domain):
            message = ("allowed_domains accepts only domains, not URLs. "
                       "Ignoring URL entry %s in allowed_domains." % domain)
            warnings.warn(message, URLWarning)
    domains = [re.escape(d) for d in allowed_domains if d is not None and not url_pattern.match(d)]
    regex = r'^(.*\.)?(%s)$' % '|'.join(domains)
    return re.compile(regex)

